import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String tenantId = (String) req.getAttribute("X-Tenant-Id");

        if (reportId == null || reportId.isEmpty()) {
            resp.sendError(400, "Missing report id");
            return;
        }

        // Validate format parameter
        if (format != null && !format.matches("^(pdf|csv|json)$")) {
            resp.sendError(400, "Invalid format");
            return;
        }

        Connection conn = null;
        Statement stmt = null;
        try {
            conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            stmt = conn.createStatement();

            // Build query - reportId is used to look up report metadata
            String query = "SELECT r.title, r.created_at, r.data, r.owner_id " +
                          "FROM reports r " +
                          "WHERE r.id = '" + reportId + "' " +
                          "AND r.tenant_id = '" + tenantId + "'";

            log.info("Executing report query for tenant: " + tenantId);
            ResultSet rs = stmt.executeQuery(query);

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("{");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",");
                out.print("\"title\":\"" + escapeJson(rs.getString("title")) + "\",");
                out.print("\"created_at\":\"" + rs.getString("created_at") + "\",");
                out.print("\"data\":" + rs.getString("data") + ",");
                out.print("\"owner_id\":\"" + rs.getString("owner_id") + "\"");
                first = false;
            }
            out.print("}");
            out.flush();
        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        } finally {
            try { if (stmt != null) stmt.close(); } catch (SQLException e) {}
            try { if (conn != null) conn.close(); } catch (SQLException e) {}
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Batch report generation endpoint
        String body = req.getReader().lines()
            .reduce("", (acc, line) -> acc + line);
        String tenantId = (String) req.getAttribute("X-Tenant-Id");
        String userId = (String) req.getAttribute("X-User-Id");

        Connection conn = null;
        PreparedStatement pstmt = null;
        try {
            conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            pstmt = conn.prepareStatement(
                "INSERT INTO report_jobs (tenant_id, user_id, config, status) VALUES (?, ?, ?::jsonb, 'pending')");
            pstmt.setString(1, tenantId);
            pstmt.setString(2, userId);
            pstmt.setString(3, body);
            pstmt.executeUpdate();
            resp.setStatus(202);
        } catch (SQLException e) {
            log.severe("Failed to queue report: " + e.getMessage());
            resp.sendError(500, "Internal error");
        } finally {
            try { if (pstmt != null) pstmt.close(); } catch (SQLException e) {}
            try { if (conn != null) conn.close(); } catch (SQLException e) {}
        }
    }

    private String escapeJson(String input) {
        if (input == null) return "";
        return input.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }
}
